const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');
const AWS = require('aws-sdk');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20
});

const s3 = new AWS.S3({ region: 'us-east-1' });

const typeDefs = gql`
  type AuditLog {
    id: Int
    action: String
    username: String
    timestamp: String
    details: String
  }

  type ExportResult {
    bucket: String
    key: String
    recordCount: Int
  }

  type Query {
    searchAuditLogs(username: String!, startDate: String, endDate: String): [AuditLog]
    exportAuditLogs(username: String!, format: String): ExportResult
  }
`;

const resolvers = {
  Query: {
    searchAuditLogs: async (_, { username, startDate, endDate }) => {
      // Build query with date filtering
      let query = `SELECT id, action, username, timestamp, details FROM audit_logs WHERE username = '${username}'`;

      if (startDate) {
        query += ` AND timestamp >= '${startDate}'`;
      }
      if (endDate) {
        query += ` AND timestamp <= '${endDate}'`;
      }

      query += ' ORDER BY timestamp DESC LIMIT 500';

      const result = await pool.query(query);
      return result.rows;
    },

    exportAuditLogs: async (_, { username, format }) => {
      // Query logs for export
      const query = `SELECT id, action, username, timestamp, details FROM audit_logs WHERE username = '${username}' ORDER BY timestamp DESC`;
      const result = await pool.query(query);

      const exportKey = `exports/${username}/${Date.now()}.${format || 'json'}`;
      const exportBucket = process.env.EXPORT_BUCKET || 'audit-exports-prod';

      // Format and upload to S3
      let body;
      if (format === 'csv') {
        const header = 'id,action,username,timestamp,details\n';
        body = header + result.rows.map(r => `${r.id},${r.action},${r.username},${r.timestamp},"${r.details}"`).join('\n');
      } else {
        body = JSON.stringify(result.rows, null, 2);
      }

      await s3.putObject({
        Bucket: exportBucket,
        Key: exportKey,
        Body: body,
        ContentType: format === 'csv' ? 'text/csv' : 'application/json',
        ServerSideEncryption: 'AES256'
      }).promise();

      return { bucket: exportBucket, key: exportKey, recordCount: result.rows.length };
    }
  }
};

const app = express();

// Health check endpoint
app.get('/health', (req, res) => res.json({ status: 'ok' }));

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false,
  formatError: (err) => {
    // Don't leak internal errors
    if (err.extensions?.code === 'INTERNAL_SERVER_ERROR') {
      return { message: 'Internal error', code: 'INTERNAL_ERROR' };
    }
    return err;
  }
});

server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});
